// ==/UserScript==

(()=>{
"use strict";
const ASSETS={"wallpapers":[{"id":"moonlit-castle","name":"Moonlit Castle","dim":22,"group":"Moonlit & Fantasy","appearance":"dark","uri":"data:image/webp;base64,"},{"id":"midnight-tulips","name":"Midnight Tulips","dim":8,"group":"Moonlit & Fantasy","appearance":"dark","uri":"data:image/webp;base64,"},{"id":"moonlit-romance","name":"Prince & Princess","dim":14,"group":"Moonlit & Fantasy","appearance":"dark","uri":"data:image/webp;base64,"},{"id":"arcane-library","name":"Arcane Library","dim":16,"group":"Dark Academia","appearance":"dark","uri":"data:image/webp;base64,"},{"id":"silent-king","name":"The Silent King","dim":10,"group":"Discipline & Stoicism","appearance":"dark","uri":"data:image/webp;base64,"}],"victor":{"idle":["data:image/webp;base64,","data:image/webp;base64,UklGRtAAAABXRUJQVlA4TMMAAAAvDwAFEFegppEU6A4QQKjeGv/SkKOmkRTo7lBA+Qqgxb8mNCiJZIU6/zSODnj6l6HBVwgEkuxWHi8AAHSbuznztiMixL1H2Q8ZBs5bW2ubayawPcFnUmGMtEEsQkTmsDxACtKXn73MyRAR/Q9AEADu5m4AGd3oABnSUIS8mwOSVQt3mltAYnp44BTi3oBoinNAVH8e6GPKHiSFkB2cdFP0eVfcjzFkZ83p9w/5ffOrrKp6mHerEGOctnVnrbVtBXXTVAAA"],"walk":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"sleep":["data:image/webp;base64,UklGRpQAAABXRUJQVlA4TIgAAAAvFMAEED+gppEUOHoHCKD8KVHSRhK0j4KFiw4fPf+aTgORAIQuaz7o/l/xQZz/AOC33Wa5G5Kb+YgKHEeSJDU1Hiy3B5iAA6cFGEDE0LxB0qz/SF/9I/o/Afx5I32loig6LoN05bxGEQa7HttyGEiKdfTxl9y1GGSXJkkGsU4+FH3Rgkd+njIA","data:image/webp;base64,UklGRpQAAABXRUJQVlA4TIgAAAAvFMAEED+gppEUOHoHCKD8KVHSRhK0j4KFiw4fPf+aTgORAIQuaz7o/l/xQZz/AOC33Wa5G5Kb+YgKHEeS5CjVHpw+D84EHDhlAQYQMTRvOeM/f/4R/U/+WogGoG3nduYpaKrqzDYFN2ed1+MusJ3nGqsgbEf4ENRmb7YFeW5xaZd2gsj6PSwA"]}};
const STYLES="/* Background is on the document, NOT a full-screen positioned overlay. */\nhtml.ds-active {\n  color-scheme: dark !important;\n  background: #091326 !important;\n  background-image: linear-gradient(rgba(var(--ds-overlay-rgb, 2, 6, 14), var(--ds-dim, .18)),rgba(var(--ds-overlay-rgb, 2, 6, 14), var(--ds-dim, .18))),var(--ds-wall) !important;\n  background-size: cover !important;\n  background-position: var(--ds-position, 50%) center !important;\n  background-repeat: no-repeat !important;\n  background-attachment: fixed !important;\n  --main-surface-primary: transparent;\n}\nhtml.ds-active body,\nhtml.ds-active #root,\nhtml.ds-active #root > div {\n  background-color: transparent !important;\n  background-image: none !important;\n}\nhtml.ds-active main,\nhtml.ds-active [role=\"main\"],\nhtml.ds-active #thread,\nhtml.ds-active [data-testid=\"conversation-turns\"],\nhtml.ds-active .bg-token-main-surface-primary {\n  background-color: transparent !important;\n  background-image: none !important;\n}\n/* Leave the sidebar opaque and readable. */\nhtml.ds-active #sidebar,\nhtml.ds-active [data-testid=\"sidebar\"] {\n  background-color: rgba(7, 12, 24, .98) !important;\n}\n/* Remove opaque outer dock layers without changing the conversation or sidebar. */\nhtml.ds-active .ds-dock,\nhtml.ds-active #thread-bottom,\nhtml.ds-active #thread-bottom-container {\n  background: transparent !important;\n  background-image: none !important;\n  box-shadow: none !important;\n  backdrop-filter: none !important;\n  -webkit-backdrop-filter: none !important;\n}\nhtml.ds-active .ds-dock::before,\nhtml.ds-active .ds-dock::after,\nhtml.ds-active #thread-bottom::before,\nhtml.ds-active #thread-bottom::after,\nhtml.ds-active #thread-bottom-container::before,\nhtml.ds-active #thread-bottom-container::after {\n  background: transparent !important;\n  background-image: none !important;\n  box-shadow: none !important;\n  backdrop-filter: none !important;\n  -webkit-backdrop-filter: none !important;\n}\nhtml.ds-active .ds-composer,\nhtml.ds-active [data-testid=\"composer-root\"] {\n  background: #0d121c !important;\n  background-image: none !important;\n  color: #f1f3fa !important;\n  border: 1px solid rgba(228, 209, 170, .52) !important;\n  border-radius: 21px !important;\n  box-shadow: 0 6px 24px rgba(0,0,0,.35) !important;\n  backdrop-filter: none !important;\n  -webkit-backdrop-filter: none !important;\n}\n\nhtml.ds-active .ds-composer [contenteditable=\"true\"],\nhtml.ds-active .ds-composer textarea {\n  color: #f1f3fa !important;\n  background: transparent !important;\n}\n#dreamscape-app {\n  position: fixed;\n  width: 0;\n  height: 0;\n  top: 0;\n  left: 0;\n  pointer-events: none;\n  z-index: 2147483000;\n  color: #eaf0fa;\n  font: 13px system-ui, sans-serif;\n}\n#dreamscape-app * {box-sizing: border-box;}\n#dreamscape-app [hidden], #ds-victor[hidden] {display: none !important;}\n#dreamscape-app .ds-launch {\n  position: fixed;right: 17px;bottom: 18px;width: 40px;height: 40px;\n  border-radius: 50%;border: 1px solid rgba(228, 209, 170, .58);\n  color: #e8d6b2;background: #121d30;\n  cursor: pointer;pointer-events: auto;font-size: 24px;box-shadow: 0 4px 17px #0008;\n}\n#dreamscape-app .ds-panel {\n  position: fixed;right: 17px;bottom: 68px;width: min(320px, calc(100vw - 34px));\n  max-height: min(75vh, 625px);overflow-y: auto;\n  color: #eaf0fa;background: #111b2d;\n  border: 1px solid #ffffff29;border-radius: 15px;pointer-events: auto;\n  padding: 17px;box-shadow: 0 15px 38px #000c;\n}\n#dreamscape-app .ds-heading {display: flex;align-items: center;justify-content: space-between;margin-bottom: 16px;}\n#dreamscape-app .ds-heading strong {font-size: 15px;}\n#dreamscape-app .ds-heading button {color: inherit;background: none;border: 0;font-size: 23px;cursor: pointer;}\n#dreamscape-app label {display: block;margin: 12px 0 6px;line-height: 1.5;}\n#dreamscape-app .ds-panel select {\n  width: 100%;padding: 9px 10px;border: 1px solid #ffffff33;\n  color: #f0f4ff;background: #0c1526;border-radius: 8px;\n}\n#dreamscape-app .ds-panel input[type=\"range\"] {width: 100%;accent-color: #dfc895;}\n/* Native checkboxes exist already, but ChatGPT may hide their default appearance. */\n#dreamscape-app .ds-panel .ds-choice {\n  display:flex !important;align-items:center;gap:11px;min-height:39px;\n  margin:6px 0;padding:8px 10px;border-radius:9px;\n  border:1px solid rgba(227,211,183,.16);background:rgba(255,255,255,.045);\n  color:#eef2fa;cursor:pointer;line-height:1.35;\n}\n#dreamscape-app .ds-panel .ds-choice:hover {background:rgba(255,255,255,.09);}\n#dreamscape-app .ds-panel .ds-choice input[type=\"checkbox\"] {\n  appearance:none !important;-webkit-appearance:none !important;\n  display:grid !important;place-content:center !important;\n  flex:0 0 20px !important;position:static !important;\n  width:20px !important;height:20px !important;margin:0 !important;\n  visibility:visible !important;opacity:1 !important;\n  border:1.5px solid #d8c49e !important;border-radius:5px !important;\n  background:#0b162a !important;cursor:pointer !important;\n}\n#dreamscape-app .ds-panel .ds-choice input[type=\"checkbox\"]:checked {\n  border-color:#e7d5ad !important;background:#dfc998 !important;\n}\n#dreamscape-app .ds-panel .ds-choice input[type=\"checkbox\"]:checked::before {\n  content:'✓';font-size:15px;font-weight:800;line-height:1;color:#112039;\n}\n#dreamscape-app .ds-panel .ds-choice input[type=\"checkbox\"]:focus-visible {\n  outline:2px solid white !important;outline-offset:3px !important;\n}\n\n#dreamscape-app .ds-actions {display: flex;gap: 10px;margin: 12px 0;align-items: center;}\n#dreamscape-app .ds-actions button,\n#dreamscape-app .ds-upload-label {\n  background: #24314a;border: 1px solid #ffffff33;\n  border-radius: 8px;color: #f0f4ff;padding: 8px 10px;margin: 0;cursor: pointer;\n}\n#dreamscape-app .ds-separator {height: 1px;background: #ffffff20;margin-top: 15px;}\n#dreamscape-app .ds-panel small {display: block;line-height: 1.5;opacity: .65;margin-top: 14px;}\n#dreamscape-app .ds-status {font-size: 12px;line-height: 1.5;color: #f2d8a3;margin: 10px 0;}\n/* Victor is an accessible button: clicking / Enter / Space gives him a little hop. */\n#ds-victor {\n  position: fixed;width: 74px;height: 59px;image-rendering: pixelated;\n  display:block;margin:0;padding:0;border:0;background:transparent;\n  pointer-events: auto;cursor:pointer;z-index: 2147482999;\n  filter: drop-shadow(0 2px 2px #0008);\n  -webkit-tap-highlight-color: transparent;\n}\n#ds-victor canvas {width:100%;height:100%;display:block;image-rendering:pixelated;pointer-events:none;}\n#ds-victor:focus-visible {outline:2px solid #e9d3a0;outline-offset:2px;border-radius:8px;}\n#ds-victor .ds-victor-heart {\n  position:absolute;top:-13px;right:4px;color:#ff9cae;font-size:19px;\n  text-shadow:0 2px 5px #000b;opacity:0;pointer-events:none;\n}\n#ds-victor.ds-petted canvas {animation:ds-victor-hop 700ms ease-out both;}\n#ds-victor.ds-petted .ds-victor-heart {animation:ds-victor-heart 800ms ease-out both;}\n@keyframes ds-victor-hop {\n  0%,100% {transform:translateY(0)}\n  39% {transform:translateY(-13px)}\n  65% {transform:translateY(-5px)}\n}\n@keyframes ds-victor-heart {\n  0% {opacity:0;transform:translateY(5px) scale(.7)}\n  22%,65% {opacity:1}\n  100% {opacity:0;transform:translateY(-15px) scale(1.08)}\n}\n@media (prefers-reduced-motion: reduce) {\n  #ds-victor {transition:none !important;}\n  #ds-victor.ds-petted canvas {animation:none;}\n  #ds-victor.ds-petted .ds-victor-heart {animation:none;opacity:1;}\n}\n\n#dreamscape-app .ds-wall-preview {height:116px;width:100%;margin:11px 0 15px;border-radius:10px;border:1px solid #ffffff23;background-color:#0a1120;background-position:center;background-size:cover;}\n#dreamscape-app .ds-hint {display:block;color:#bcc7d7;font-size:11px;line-height:1.35;margin:5px 0 12px;}\n\n/* Temporary theme-reveal sheet, never intercepts user input. */\n.ds-wallpaper-reveal {\n  position:fixed;inset:0;z-index:2147482500;\n  background-size:cover;background-repeat:no-repeat;\n  pointer-events:none;user-select:none;\n  will-change:clip-path;\n}\n@media (prefers-reduced-motion: reduce) {\n  .ds-wallpaper-reveal {display:none !important;}\n}\n";
  // Local-only preferences and wallpaper storage. No external APIs.
  const STORAGE_KEY = 'dreamscape-public-v1';
  const STORE_DB = 'dreamscape-wallpapers-v1';
  const STORE = 'wallpapers';
  const DEFAULTS = {enabled:true, theme:'moonlit-castle', victor:true, motion:true, dimOverrides:{}, positionOverrides:{}};
  let userSettings = {};
  try { userSettings = JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}') || {}; } catch {}
  const settings = {...DEFAULTS, ...userSettings};
  // Migrate deprecated translucent-composer setting without affecting other preferences.
  delete settings.glassComposer;
  settings.dimOverrides = settings.dimOverrides && typeof settings.dimOverrides === 'object' ? settings.dimOverrides : {};
  settings.positionOverrides = settings.positionOverrides && typeof settings.positionOverrides === 'object' ? settings.positionOverrides : {};
  function saveSettings() {
    try {localStorage.setItem(STORAGE_KEY,JSON.stringify(settings));}catch(err){console.warn('[Dreamscape] Could not save preferences',err);}
  }
  function openWallDB(){
    return new Promise((resolve,reject)=>{
      const request=indexedDB.open(STORE_DB,1);
      request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains(STORE))request.result.createObjectStore(STORE,{keyPath:'id'});};
      request.onsuccess=()=>resolve(request.result);
      request.onerror=()=>reject(request.error);
    });
  }
  async function dbOperation(mode,callback){
    const db=await openWallDB();
    try {return await new Promise((resolve,reject)=>{
      const tx=db.transaction(STORE,mode);
      const request=callback(tx.objectStore(STORE));
      request.onsuccess=()=>resolve(request.result);
      request.onerror=()=>reject(request.error);
      tx.onabort=()=>reject(tx.error||new Error('Wallpaper storage transaction aborted'));
    });} finally {db.close();}
  }
  const listCustomWallpapers=()=>dbOperation('readonly',store=>store.getAll());
  const putCustomWallpaper=wallpaper=>dbOperation('readwrite',store=>store.put(wallpaper));
  const deleteCustomWallpaper=id=>dbOperation('readwrite',store=>store.delete(id));

  async function optimizeWallpaper(file){
    if (!['image/png','image/jpeg','image/webp'].includes(file.type)) throw new Error('Use a PNG, JPG or WebP image.');
    if (file.size>15*1024*1024)throw new Error('Choose an image smaller than 15 MB.');
    const localURL=URL.createObjectURL(file);
    let bitmap;
    try {
      const img=new Image();
      img.src=localURL;
      await img.decode();
      if (!img.naturalWidth || !img.naturalHeight) throw new Error('Cannot open this image.');
      const ratio=Math.min(1,2400/img.naturalWidth,1600/img.naturalHeight);
      const canvas=document.createElement('canvas');
      canvas.width=Math.max(1,Math.round(img.naturalWidth*ratio));
      canvas.height=Math.max(1,Math.round(img.naturalHeight*ratio));
      canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);
      const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',0.84));
      if(!blob)throw new Error('Unable to optimize image.');
      return blob;
    } finally {URL.revokeObjectURL(localURL);}
  }

  const customWallpapers=new Map();
  const customObjectUrls=new Map();
  const builtins=ASSETS.wallpapers;
  const findWallpaper=id=>builtins.find(w=>w.id===id)||customWallpapers.get(id);
  const allWallpapers=()=>[...builtins,...customWallpapers.values()];
  const activeWallpaper=()=>findWallpaper(settings.theme)||builtins[0];
  const clamp=(x,a,b)=>Math.min(b,Math.max(a,x));
  function wallpaperDim(id){const wall=findWallpaper(id);return clamp(Number(settings.dimOverrides[id]??wall?.dim??22)||0,0,75);}
  function wallpaperPosition(id){return clamp(Number(settings.positionOverrides[id]??50)||0,0,100);}
  // Reveal only user-selected wallpapers; initial load and resizing remain instant.
  let displayedWallpaperId=null;
  let wallpaperReveal=null;
  const cornerPoints=['0% 0%','100% 0%','0% 100%','100% 100%'];
  function applyWallpaperBackground(id,src,dim,position){
    if(src)document.documentElement.style.setProperty('--ds-wall',`url("${src}")`);
    document.documentElement.style.setProperty('--ds-dim',String(dim/100));
    document.documentElement.style.setProperty('--ds-position',position+'%');
    displayedWallpaperId=id;
  }
  function revealWallpaper(wallpaper,src,dim,position){
    // A new selection interrupts the previous reveal cleanly.
    wallpaperReveal?.finish();
    wallpaperReveal=null;
    if(!document.body || !window.Animation || !document.documentElement.animate ||
       matchMedia('(prefers-reduced-motion: reduce)').matches){
      applyWallpaperBackground(wallpaper.id,src,dim,position);
      return;
    }
    const overlay=document.createElement('div');
    overlay.className='ds-wallpaper-reveal';
    overlay.setAttribute('aria-hidden','true');
    overlay.style.backgroundImage=`linear-gradient(rgba(2,6,14,${dim/100}),rgba(2,6,14,${dim/100})),url("${src}")`;
    overlay.style.backgroundPosition=position+'% center';
    document.body.append(overlay);
    const corner=cornerPoints[Math.floor(Math.random()*cornerPoints.length)];
    const animation=overlay.animate([
      {clipPath:`circle(0px at ${corner})`},
      {clipPath:`circle(150vmax at ${corner})`}
    ],{duration:720,easing:'cubic-bezier(.22,1,.36,1)',fill:'forwards'});
    let finished=false;
    const finish=()=>{
      if(finished)return;
      finished=true;
      applyWallpaperBackground(wallpaper.id,src,dim,position);
      animation.cancel();overlay.remove();
      if(wallpaperReveal?.finish===finish)wallpaperReveal=null;
    };
    wallpaperReveal={finish};
    animation.finished.then(finish,()=>{});
  }
  function setWallpaperProperties(animateChange=false){
    const wallpaper=activeWallpaper();
    if(!findWallpaper(settings.theme)&&!String(settings.theme).startsWith('custom-'))settings.theme=wallpaper.id;
    const src=wallpaper.uri||customObjectUrls.get(wallpaper.id);
    const dim=wallpaperDim(wallpaper.id);
    const position=wallpaperPosition(wallpaper.id);
    if(animateChange && settings.enabled && displayedWallpaperId && displayedWallpaperId!==wallpaper.id)
      revealWallpaper(wallpaper,src,dim,position);
    else {wallpaperReveal?.finish();wallpaperReveal=null;applyWallpaperBackground(wallpaper.id,src,dim,position);}
    // Built-in themes share a dark overlay, keeping conversation text readable.
    document.documentElement.classList.remove('ds-parchment');
    document.documentElement.style.setProperty('--ds-overlay-rgb','2,6,14');
    document.documentElement.classList.toggle('ds-active',!!settings.enabled);
    if(victorElement)positionVictor();
    saveSettings();
  }
  async function loadCustomWallpapers(){
    try {
      const all=await listCustomWallpapers();
      for(const item of all){
        if(!item.blob)continue;
        customWallpapers.set(item.id,{id:item.id,name:item.name,dim:item.dim??20,custom:true});
        customObjectUrls.set(item.id,URL.createObjectURL(item.blob));
      }
    }catch(err){console.warn('[Dreamscape] Custom wallpapers unavailable:',err);showStatus('Custom wallpaper storage unavailable in this browser.');}
    // Unknown or removed built-in selections fall back to Moonlit Castle.
    // Do this after IndexedDB loads so saved custom choices are not reset.
    if(!findWallpaper(settings.theme))settings.theme=builtins[0].id;
    refreshThemePicker();setWallpaperProperties();
  }
  async function addWallpaper(file){
    const optimized=await optimizeWallpaper(file);
    const id='custom-'+(crypto.randomUUID?.()||String(Date.now())+'-'+Math.random().toString(36).slice(2));
    const name=(file.name||'My wallpaper').replace(/\.[^.]+$/,'').slice(0,62);
    await putCustomWallpaper({id,name,dim:20,blob:optimized});
    const url=URL.createObjectURL(optimized);
    customObjectUrls.set(id,url);
    customWallpapers.set(id,{id,name,dim:20,custom:true});
    settings.theme=id;saveSettings();refreshThemePicker();setWallpaperProperties(true);syncControls();
    showStatus(`Added “${name}” to My Wallpapers.`);
  }
  async function removeWallpaper(id){
    if(!customWallpapers.has(id))return;
    await deleteCustomWallpaper(id);
    customWallpapers.delete(id);
    URL.revokeObjectURL(customObjectUrls.get(id));
    customObjectUrls.delete(id);
    delete settings.dimOverrides[id];delete settings.positionOverrides[id];
    if(settings.theme===id)settings.theme=builtins[0].id;
    refreshThemePicker();setWallpaperProperties();syncControls();showStatus('Custom wallpaper deleted.');
  }

  // Victor's movement is limited to a small patrol along the right corner of the composer.
  // Preloading and drawing into one fixed canvas avoids sprite-size jitter and ghost images.
  let victorElement=null;
  let victorCanvas=null;
  let victorContext=null;
  let victorImages={};
  let petTimer=null;
  let petStart=performance.now();
  let petTravel=0;
  let lastTyping=0;
  let lastFrameKey='';
  let petReactionUntil=0;
  let petReactionTimer=null;
  const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
  const petSequences=ASSETS.victor;
  const VICTOR_BOX_WIDTH=74;
  const VICTOR_BOX_HEIGHT=59;

  // Anchor Victor to the model-effort label ("High" in the desktop composer),
  // not the composer's far-right send button. Keep a predictable fallback if the
  // selector changes or a different effort is selected.
  function effortControlRect(composerRect){
    if(!composer)return null;
    const controls=composer.querySelectorAll('button,[role="button"],[data-testid*="model"],span');
    const candidates=[];
    for(const el of controls){
      const label=el.textContent?.replace(/\s+/g,' ').trim().toLowerCase();
      if(!['high','extra high','medium','low','instant','auto','thinking'].includes(label))continue;
      const r=el.getBoundingClientRect();
      if(r.width<8 || r.height<8 || r.width>230 || r.height>95 ||
         r.left<composerRect.left+composerRect.width*.45 ||
         r.right>composerRect.right+10 ||
         r.top<composerRect.top-10 || r.bottom>composerRect.bottom+10)continue;
      const priority=(label==='high'?100:0)+(el.matches('button,[role="button"]')?10:0);
      candidates.push({rect:r,priority});
    }
    candidates.sort((a,b)=>b.priority-a.priority);
    return candidates[0]?.rect||null;
  }

  function positionVictor(){
    if(!victorElement)return;
    if(!settings.enabled||!settings.victor||!composer){victorElement.hidden=true;return;}
    const rect=composer.getBoundingClientRect();
    if(rect.top<0||rect.top>innerHeight||rect.width<200){victorElement.hidden=true;return;}
    victorElement.hidden=false;
    const effort=effortControlRect(rect);
    // Align the cat's middle with the middle of High; if the UI changes,
    // stay toward the right without drifting over the send/microphone buttons.
    const homeCenter=effort?(effort.left+effort.right)/2:
      rect.right-Math.max(105,Math.min(165,rect.width*.18));
    const startX=Math.min(rect.right-VICTOR_BOX_WIDTH-12,
      Math.max(rect.left+12,homeCenter-VICTOR_BOX_WIDTH/2));
    const patrolLimit=Math.min(70,Math.max(20,rect.width*.12));
    const x=Math.min(innerWidth-VICTOR_BOX_WIDTH,
      Math.max(rect.left+8,startX-patrolLimit*petTravel));
    const y=Math.max(0,rect.top-VICTOR_BOX_HEIGHT+8);
    victorElement.style.left=Math.round(x)+'px';
    victorElement.style.top=Math.round(y)+'px';
    victorElement.dataset.anchor=effort?'effort':'fallback';
  }

  function drawFrame(sequence,frame,facing){
    if(!victorContext)return;
    const key=sequence+':'+frame+':'+facing;
    if(key===lastFrameKey)return;
    lastFrameKey=key;
    const image=victorImages[sequence]?.[frame];
    if(!image?.complete||!image.naturalWidth)return;
    const canvas=victorCanvas;
    victorContext.clearRect(0,0,canvas.width,canvas.height);
    const scale=Math.min(5.06,91.08/image.naturalHeight,(canvas.width-8)/image.naturalWidth,(canvas.height-8)/image.naturalHeight);
    const width=Math.round(image.naturalWidth*scale);
    const height=Math.round(image.naturalHeight*scale);
    const x=Math.round((canvas.width-width)/2);
    const y=canvas.height-height-4;
    victorContext.save();
    if(facing==='left'){
      victorContext.translate(canvas.width,0);
      victorContext.scale(-1,1);
    }
    victorContext.drawImage(image,x,y,width,height);
    victorContext.restore();
  }

  // 30-second patrol at the right edge. Face left going out; turn before returning.
  // At the far end Victor rests briefly, turns around, and walks right to his home position.
  function petMotion(now){
    const elapsed=((now-petStart)/1000)%30;
    const smooth=t=>t*t*(3-2*t);
    if(elapsed<5)return {mode:'idle',progress:0,facing:'left'};
    if(elapsed<8)return {mode:'walk',progress:smooth((elapsed-5)/3),facing:'left'};
    if(elapsed<10)return {mode:'idle',progress:1,facing:'left'};
    if(elapsed<11)return {mode:'idle',progress:1,facing:'right'};
    if(elapsed<14)return {mode:'walk',progress:1-smooth((elapsed-11)/3),facing:'right'};
    if(elapsed<22)return {mode:'sleep',progress:0,facing:'right'};
    return {mode:'idle',progress:0,facing:'left'};
  }

  function drawVictor(){
    if(!victorElement)return;
    const animate=settings.enabled&&settings.victor&&settings.motion&&!reduceMotion.matches;
    const now=performance.now();
    const isPetted=now<petReactionUntil;
    const action=isPetted?{mode:'idle',progress:0,facing:'right'}:
      animate?petMotion(now):{mode:'idle',progress:0,facing:'right'};
    const reacted=animate&&Date.now()-lastTyping<900;
    petTravel=action.progress;
    // Typing makes Victor look up; it doesn't make him teleport or run.
    let sequence=action.mode;
    let frame=0;
    if(isPetted)frame=Math.min(1,petSequences.idle.length-1);
    else if(sequence==='walk')frame=Math.floor(now/210)%petSequences.walk.length;
    else if(sequence==='sleep')frame=Math.floor(now/1700)%petSequences.sleep.length;
    else if(reacted)frame=1;
    else frame=Math.floor(now/3700)%7===0?1:0;
    frame=Math.min(frame,petSequences[sequence].length-1);
    victorElement.dataset.facing=action.facing;
    victorElement.dataset.motion=action.mode;
    drawFrame(sequence,frame,action.facing);
    positionVictor();
  }

  function petVictor(){
    if(!settings.enabled||!settings.victor||!victorElement)return;
    petReactionUntil=performance.now()+850;
    // A repeated click restarts the hop without adding another sprite layer.
    victorElement.classList.remove('ds-petted');
    void victorElement.offsetWidth;
    victorElement.classList.add('ds-petted');
    victorElement.dataset.reaction='petted';
    clearTimeout(petReactionTimer);
    petReactionTimer=setTimeout(()=>{
      victorElement?.classList.remove('ds-petted');
      if(victorElement)victorElement.dataset.reaction='idle';
    },850);
    drawVictor();
  }

  function installVictor(parent){
    victorElement=document.createElement('button');
    victorElement.id='ds-victor';
    victorElement.type='button';
    victorElement.setAttribute('aria-label','Pet Victor the pixel cat');
    victorElement.title='Click to pet Victor';
    victorElement.hidden=true;
    victorCanvas=document.createElement('canvas');
    victorCanvas.width=VICTOR_BOX_WIDTH*2;
    victorCanvas.height=VICTOR_BOX_HEIGHT*2;
    victorCanvas.setAttribute('aria-hidden','true');
    victorElement.append(victorCanvas);
    const heart=document.createElement('span');
    heart.className='ds-victor-heart';
    heart.textContent='♥';
    heart.setAttribute('aria-hidden','true');
    victorElement.append(heart);
    victorElement.addEventListener('click',petVictor);
    victorContext=victorCanvas.getContext('2d');
    victorContext.imageSmoothingEnabled=false;
    // Draw into a single high-DPI canvas; the fixed canvas is 15% bigger than v0.3.1.
    // Mirror the sprite for leftward movement; preserve one canvas to avoid ghosting.
    for(const [sequence,frames] of Object.entries(petSequences)){
      victorImages[sequence]=frames.map(src=>{
        const image=new Image();image.src=src;
        image.addEventListener('load',()=>{lastFrameKey='';drawVictor();},{once:true});
        return image;
      });
    }
    parent.append(victorElement);
    const typing=e=>{
      if(e.target?.closest?.('#prompt-textarea,[data-testid="composer-root"] [contenteditable="true"],textarea'))lastTyping=Date.now();
    };
    document.addEventListener('keydown',typing,{passive:true});
    petStart=performance.now();
    petTimer=setInterval(drawVictor,120);
    drawVictor();
  }

  // Conservative ChatGPT DOM adapter. Never touches chat message contents.
  let composer=null;
  let observer=null;
  let resizeObserver=null;
  let queued=false;
  let activeDockNodes=[];
  let resizeListener=null;
  function getComposer(){
    // ChatGPT may render a centered composer on New Chat and a fixed dock in a
    // conversation. Some builds also leave an invisible, older composer mounted.
    // Search ALL candidates, rather than letting a hidden first match block us.
    const visibleRect=el=>{
      if(!el||!el.isConnected)return null;
      const r=el.getBoundingClientRect();
      if(r.width<220||r.height<29||r.height>620 ||r.bottom<=0||
         r.top>=innerHeight||r.right<=0||r.left>=innerWidth)return null;
      const s=getComputedStyle(el);
      if(s.display==='none'||s.visibility==='hidden')return null;
      return r;
    };
    const visibleEditable=el=>{
      if(!el)return false;
      const r=el.getBoundingClientRect();
      const style=getComputedStyle(el);
      return style.display!=='none'&&style.visibility!=='hidden'&&
        r.width>=18&&r.height>=10&&r.bottom>0&&r.top<innerHeight;
    };
    const editorSelector='#prompt-textarea,[data-testid="composer-text-input"],[contenteditable="true"][role="textbox"],textarea';
    const candidates=[];
    for(const selector of [
      '[data-composer-surface="true"]',
      '#composer-background',
      '[data-testid="composer-background"]',
      '[data-testid="composer-root"]',
      'form:has(#prompt-textarea)',
      'form:has([data-testid="composer-text-input"])',
      'form:has([contenteditable="true"])'
    ]){
      for(const el of document.querySelectorAll(selector)){
        const rect=visibleRect(el);
        if(!rect||!Array.from(el.querySelectorAll(editorSelector)).some(visibleEditable))continue;
        if(!candidates.some(c=>c.element===el))candidates.push({element:el,rect});
      }
    }
    // The New Chat landing can use a div-based composer with no form/testid.
    // Find a compact wrapper around a visible textbox AND its controls.
    if(!candidates.length){
      for(const editor of document.querySelectorAll(editorSelector)){
        if(!visibleEditable(editor))continue;
        let node=editor.parentElement;
        for(let depth=0;node&&depth<7;node=node.parentElement,depth++){
          if(node.matches('#root,main,[role="main"],body'))break;
          const rect=visibleRect(node);
          if(rect&&node.querySelector('button,[role="button"]')){
            candidates.push({element:node,rect});break;
          }
        }
      }
    }
    // Prefer a dock near the bottom if more than one composer is genuinely
    // visible; otherwise use the centered new-chat composer.
    candidates.sort((a,b)=>{
      // A form may wrap the full-width dock; its nested painted surface is
      // the actual input. Prefer that surface over its containing form.
      if(a.element.contains(b.element))return 1;
      if(b.element.contains(a.element))return -1;
      return b.rect.bottom-a.rect.bottom;
    });
    return candidates[0]?.element||null;
  }
  function clearDockClasses(){
    for(const e of activeDockNodes)e.classList.remove('ds-dock');
    activeDockNodes=[];
  }
  // Bottom dock wrappers can be replaced or reparented when the composer expands
  // (for example, an image attachment). Do not depend on the composer identity.
  // Mark only compact ancestors around the input: never mark the chat transcript.
  function markDock(el){
    const next=new Set();
    if(el){
      const c=el.getBoundingClientRect();
      let node=el.parentElement;
      let depth=0;
      while(node && depth<18 && node!==document.body && node!==document.documentElement){
        if(node.matches('main,[role="main"],#root,#sidebar,[data-testid="sidebar"]'))break;
        // display:contents wrappers have no box. Their zero rect must not
        // terminate discovery of the actual footer/backdrop above them.
        if(getComputedStyle(node).display==='contents'){
          node=node.parentElement;depth++;continue;
        }
        const rect=node.getBoundingClientRect();
        // A real dock can span the full width, but must be near the composer
        // and short enough that it cannot be the whole conversation viewport.
        if(rect.height>Math.max(540,c.height+230) ||
           rect.top<c.top-Math.max(220,c.height+50) ||
           rect.bottom<c.top-8)break;
        next.add(node);
        node=node.parentElement;
        depth++;
      }
      for(const selector of ['#thread-bottom','#thread-bottom-container']){
        const e=document.querySelector(selector);
        if(e&&e.contains(el)){
          const r=e.getBoundingClientRect();
          if(r.height<=Math.max(540,c.height+230) && r.top>=c.top-Math.max(220,c.height+50))next.add(e);
        }
      }
      // Backdrops need not declare aria-hidden or pointer-events:none. Require
      // an empty decorative subtree instead: never strip controls or messages.
      const contentSelector='button,a,input,textarea,select,iframe,canvas,img,video,svg,[role="button"],[role="textbox"],[role="log"],[tabindex],[contenteditable]:not([contenteditable="false"]),article,[data-message-author-role]';
      const decorative=node=>!node.matches(contentSelector)&&
        !node.querySelector(contentSelector)&&!node.textContent.trim();
      const markDecoration=(node,depth=0)=>{
        next.add(node);
        if(depth<6)for(const child of node.children){
          if(!child.matches('script,style')&&decorative(child))markDecoration(child,depth+1);
        }
      };
      for(const wrapper of [...next]){
        for(const sibling of wrapper.children){
          if(sibling===el||sibling.contains(el)||sibling.matches('script,style'))continue;
          if(!decorative(sibling))continue;
          const r=sibling.getBoundingClientRect();
          if(r.width>=c.width*.9 && r.height>0 &&
             r.height<=Math.max(540,c.height+230) &&
             r.top<c.bottom && r.bottom>c.top-140)markDecoration(sibling);
        }
      }
    }
    const previous=new Set(activeDockNodes);
    for(const e of previous)if(!next.has(e))e.classList.remove('ds-dock');
    for(const e of next)if(!previous.has(e))e.classList.add('ds-dock');
    activeDockNodes=[...next];
  }
  function syncComposer(){
    queued=false;
    const next=getComposer();
    if(next!==composer){
      if(composer)composer.classList.remove('ds-composer');
      composer=next;
      if(resizeObserver)resizeObserver.disconnect();
      if(composer){composer.classList.add('ds-composer');resizeObserver?.observe(composer);}
    }
    // Expansion/reparenting can change opaque wrappers while keeping the same
    // form element, so rediscover dock ancestors on every scheduled sync.
    markDock(composer);
    positionVictor();
  }
  function scheduleSync(){if(queued)return;queued=true;requestAnimationFrame(syncComposer);}
  function startAdapter(){
    resizeObserver=new ResizeObserver(scheduleSync);
    observer=new MutationObserver(mutations=>{
      // SPA transitions can reveal a composer by changing CSS alone. Ignore
      // Dreamscape's own position/style mutations to prevent an update loop.
      if(mutations.some(m=>{
        const target=m.target;
        if(target instanceof Element && (target.id==='ds-victor'||target.closest('#dreamscape-app')))return false;
        return true;
      }))scheduleSync();
    });
    observer.observe(document.body,{childList:true,subtree:true,
      attributes:true,attributeFilter:['class','style','hidden','aria-hidden']});
    window.addEventListener('resize',scheduleSync,{passive:true});
    window.addEventListener('scroll',scheduleSync,{capture:true,passive:true});
    scheduleSync();
  }
  function stopAdapter(){
    observer?.disconnect();resizeObserver?.disconnect();clearDockClasses();
    composer?.classList.remove('ds-composer');composer=null;
  }

  let interfaceRoot=null;
  function showStatus(message){
    if(!interfaceRoot)return;
    const status=interfaceRoot.querySelector('.ds-status');
    status.textContent=message;
    status.hidden=false;
  }
  function refreshThemePicker(){
    if(!interfaceRoot)return;
    const select=interfaceRoot.querySelector('.ds-theme');
    select.replaceChildren();
    const groups=new Map();
    for(const wall of builtins){
      const label=wall.group||'Dreamscape Originals';
      if(!groups.has(label)){
        const optgroup=document.createElement('optgroup');optgroup.label=label;
        groups.set(label,optgroup);select.append(optgroup);
      }
      groups.get(label).append(new Option(wall.name,wall.id));
    }
    if(customWallpapers.size){
      const custom=document.createElement('optgroup');custom.label='My Wallpapers';
      for(const wall of customWallpapers.values())custom.append(new Option(wall.name,wall.id));
      select.append(custom);
    }
    select.value=settings.theme;
  }
  function syncControls(){
    if(!interfaceRoot)return;
    const wallpaper=activeWallpaper();
    interfaceRoot.querySelector('.ds-theme').value=wallpaper.id;
    interfaceRoot.querySelector('.ds-dim').value=wallpaperDim(wallpaper.id);
    interfaceRoot.querySelector('.ds-dim-value').textContent=wallpaperDim(wallpaper.id)+'%';
    interfaceRoot.querySelector('.ds-overlay-label').textContent='Darken wallpaper';
    interfaceRoot.querySelector('.ds-position').value=wallpaperPosition(wallpaper.id);
    interfaceRoot.querySelector('.ds-position-value').textContent=wallpaperPosition(wallpaper.id)+'%';
    interfaceRoot.querySelector('.ds-victor-check').checked=!!settings.victor;
    interfaceRoot.querySelector('.ds-motion-check').checked=!!settings.motion;
    interfaceRoot.querySelector('.ds-active-check').checked=!!settings.enabled;
    interfaceRoot.querySelector('.ds-delete').hidden=!wallpaper.custom;
    const preview=interfaceRoot.querySelector('.ds-wall-preview');
    if(preview){
      const src=wallpaper.uri||customObjectUrls.get(wallpaper.id);
      preview.style.backgroundImage=src?`linear-gradient(rgba(2,6,14,.16),rgba(2,6,14,.16)),url("${src}")`:'none';
      preview.setAttribute('aria-label',wallpaper.name+' preview');
    }
  }
  function installUI(){
    interfaceRoot=document.createElement('div');interfaceRoot.id='dreamscape-app';
    interfaceRoot.innerHTML=`
      <button class="ds-launch" type="button" aria-label="Open Dreamscape settings" aria-expanded="false" aria-controls="ds-settings" title="Dreamscape settings">☾</button>
      <section class="ds-panel" id="ds-settings" role="region" aria-label="Dreamscape settings" hidden>
        <div class="ds-heading"><strong>☾ Dreamscape</strong><button class="ds-close" type="button" aria-label="Close settings">×</button></div>
        <label for="ds-theme">Wallpaper</label>
        <select class="ds-theme" id="ds-theme"></select>
        <div class="ds-wall-preview" role="img" aria-label="Selected wallpaper preview"></div>
        <label for="ds-dim"><span class="ds-overlay-label">Darken wallpaper</span> <output class="ds-dim-value"></output></label>
        <input class="ds-dim" id="ds-dim" type="range" min="0" max="75" step="1">
        <label for="ds-position">Horizontal position <output class="ds-position-value"></output></label>
        <input class="ds-position" id="ds-position" type="range" min="0" max="100" step="5">
        <span class="ds-hint">Changes wallpaper cropping: 0% left · 50% center · 100% right.</span>
        <div class="ds-actions">
          <label class="ds-upload-label" for="ds-upload">＋ Add wallpaper</label>
          <input class="ds-upload" id="ds-upload" type="file" accept="image/png,image/jpeg,image/webp" hidden>
          <button class="ds-delete" type="button" hidden>Delete selected</button>
        </div>
        <div class="ds-separator"></div>
        <label class="ds-choice"><input class="ds-victor-check" type="checkbox"> Victor · pixel companion</label>
        <label class="ds-choice"><input class="ds-motion-check" type="checkbox"> Gentle animations</label>
        <label class="ds-choice"><input class="ds-active-check" type="checkbox"> Enable Dreamscape</label>
        <div class="ds-status" role="status" hidden></div>
        <small>Your wallpapers and settings stay in this browser. Nothing is uploaded.</small>
      </section>`;
    document.body.append(interfaceRoot);
    const get=s=>interfaceRoot.querySelector(s);
    const launch=get('.ds-launch');const panel=get('.ds-panel');
    const toggle=open=>{
      panel.hidden=!open;launch.setAttribute('aria-expanded',String(open));
      if(open)syncControls();
    };
    launch.addEventListener('click',()=>toggle(panel.hidden));
    get('.ds-close').addEventListener('click',()=>toggle(false));
    document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden)toggle(false);});
    get('.ds-theme').addEventListener('change',e=>{settings.theme=e.target.value;setWallpaperProperties(true);syncControls();});
    get('.ds-dim').addEventListener('input',e=>{settings.dimOverrides[settings.theme]=Number(e.target.value);setWallpaperProperties();syncControls();});
    get('.ds-position').addEventListener('input',e=>{settings.positionOverrides[settings.theme]=Number(e.target.value);setWallpaperProperties();syncControls();});
    for(const [selector,key] of [['.ds-victor-check','victor'],['.ds-motion-check','motion'],['.ds-active-check','enabled']]){
      get(selector).addEventListener('change',e=>{settings[key]=e.target.checked;setWallpaperProperties();saveSettings();drawVictor();});
    }
    get('.ds-upload').addEventListener('change',async e=>{
      const file=e.target.files?.[0];if(!file)return;
      try{await addWallpaper(file);}catch(err){showStatus(err?.message||'Could not add wallpaper.');}
      e.target.value='';
    });
    get('.ds-delete').addEventListener('click',async()=>{
      if(!customWallpapers.has(settings.theme))return;
      try{await removeWallpaper(settings.theme);}catch(err){showStatus(err?.message||'Unable to delete wallpaper.');}
    });
    refreshThemePicker();syncControls();
  }

  if(window.__DREAMSCAPE_PUBLIC_V1__)return;
  window.__DREAMSCAPE_PUBLIC_V1__=true;
  const style=document.createElement('style');
  style.id='dreamscape-public-style';
  style.textContent=STYLES;
  document.head.append(style);
  function boot(){
    if(!document.body)return;
    installUI();installVictor(interfaceRoot);
    setWallpaperProperties();startAdapter();
    loadCustomWallpapers();
  }
  if(document.body)boot();
  else document.addEventListener('DOMContentLoaded',boot,{once:true});

})();
